using System;using System.Collections.Generic;using System.IO;using System.Linq;using HabitatShift.Core;using UnityEngine;using UnityEngine.EventSystems;using UnityEngine.UI;
namespace HabitatShift.Runtime {
[Serializable] public class SaveV2 {public int version=2,highest=1,last=1;public bool music=true,sfx=true,haptics=true,vfx=true,reducedMotion=false;public List<int> completed=new List<int>();public List<Best> best=new List<Best>();public List<Charge> charges=new List<Charge>();public RuntimeState snapshot;public int snapshotLevel;}[Serializable] public class LegacyPrefs { public bool Sound=true,Haptics=true,ReducedMotion; } [Serializable] public class Best{public int level,moves;}[Serializable] public class Charge{public int level,nest,garden,trim;}
public class SproutlingMotion:MonoBehaviour
{
    Vector3 basePosition,baseScale;
    float phase;
    void Awake(){phase=UnityEngine.Random.value*6f;}
    public void SetPose(Vector3 position,Vector3 scale){basePosition=position;baseScale=scale;}
    void Update(){var t=Time.time+phase;transform.localPosition=basePosition+Vector3.up*Mathf.Sin(t*1.4f)*.025f;transform.localScale=baseScale*(1f+Mathf.Sin(t*2f)*.02f);}
}public sealed class HabitatBootstrap:MonoBehaviour{
static HabitatBootstrap instance;CatalogDto catalog;RulesetDto rules;ContinuousSession session;SaveV2 save;Camera cam;Canvas canvas;Sprite white;AudioSource audio;HabitatPresentation presentation;int current;bool active;string assistHabitat,assistSprout;AssistKind? assist;readonly Dictionary<string,GameObject> world=new Dictionary<string,GameObject>();readonly List<GameObject> ui=new List<GameObject>();Text hud;float winAt=-1;int fittedWidth,fittedHeight;Rect fittedSafe;
[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Create(){if(instance==null)new GameObject("Habitat Shift").AddComponent<HabitatBootstrap>();}
void Awake(){if(instance!=null&&instance!=this){Destroy(gameObject);return;}instance=this;DontDestroyOnLoad(gameObject);Application.targetFrameRate=60;Screen.orientation=ScreenOrientation.Portrait;try{catalog=CatalogLoader.Load(out rules);}catch(Exception e){Debug.LogError(e);return;}save=Load();MakeInfra();ShowHome();}
void MakeInfra(){cam=Camera.main;if(cam==null){cam=new GameObject("Habitat Camera").AddComponent<Camera>();cam.tag="MainCamera";}cam.orthographic=true;cam.backgroundColor=new Color(.16f,.25f,.20f);cam.transform.position=new Vector3(4,-3.5f,-10);audio=gameObject.AddComponent<AudioSource>();var t=new Texture2D(2,2);t.SetPixels(new[]{Color.white,Color.white,Color.white,Color.white});t.Apply();white=UnityEngine.Sprite.Create(t,new Rect(0,0,2,2),new Vector2(.5f,.5f),2);presentation=gameObject.AddComponent<HabitatPresentation>();presentation.Initialize(cam);if(FindAnyObjectByType<EventSystem>()==null)new GameObject("EventSystem",typeof(EventSystem),typeof(StandaloneInputModule));var c=new GameObject("UI",typeof(Canvas),typeof(CanvasScaler),typeof(GraphicRaycaster));canvas=c.GetComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceOverlay;canvas.sortingOrder=20;var sc=c.GetComponent<CanvasScaler>();sc.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;sc.referenceResolution=new Vector2(1080,1920);}
void Update(){if(active && (fittedWidth!=Screen.width || fittedHeight!=Screen.height || fittedSafe!=Screen.safeArea)){Fit(catalog.levels[current-1]);}if(active&&!session.Committed.won&&!EventSystem.current.IsPointerOverGameObject()){if(Input.GetMouseButtonDown(0))StartDrag(Input.mousePosition);if(Input.GetMouseButton(0))Drag(Input.mousePosition);if(Input.GetMouseButtonUp(0))EndDrag();if(Input.touchCount>0){var t=Input.GetTouch(0);if(t.phase==TouchPhase.Began)StartDrag(t.position);if(t.phase==TouchPhase.Moved||t.phase==TouchPhase.Stationary)Drag(t.position);if(t.phase==TouchPhase.Ended||t.phase==TouchPhase.Canceled)EndDrag(t.phase==TouchPhase.Canceled);}}if(winAt>0&&Time.unscaledTime>=winAt){winAt=-1;ShowResult();}}
void StartDrag(Vector2 screen){if(assist.HasValue){AssistTap(ToBoard(screen));return;}var p=ToBoard(screen);var h=session.Committed.habitats.FirstOrDefault(x=>x.shape.Any(c=>p.x>=x.anchor.x+c.x&&p.x<=x.anchor.x+c.x+1&&p.y>=x.anchor.y+c.y&&p.y<=x.anchor.y+c.y+1));if(h!=null&&session.BeginDrag(h.id,p)){Buzz();}}
void Drag(Vector2 s){if(!session.IsDragging)return;session.MovePointer(ToBoard(s));Render(session.Preview);Present();}void EndDrag(bool cancel=false){if(!session.IsDragging)return;session.EndDrag(cancel);Render(session.Committed);Present();SaveSnapshot();UpdateHud();if(session.Committed.won)Victory();}
Vector2 ToBoard(Vector2 s){return BoardViewport.FromScreen(cam,s);}
void StartLevel(int id){current=id;var restore=save.snapshotLevel==id?save.snapshot:null;session=new ContinuousSession(catalog.levels[id-1],rules,restore);active=true;winAt=-1;ClearUi();Fit(catalog.levels[id-1]);GameplayUi();Render(session.Committed);if(id==8||id==12||id==16)Tutorial(id);}
void Fit(LevelDto l){BoardViewport.Fit(cam,l);presentation.FitBackdrop(cam);fittedWidth=Screen.width;fittedHeight=Screen.height;fittedSafe=Screen.safeArea;}
void Render(RuntimeState state){presentation.Render(state,catalog.levels[current-1]);}Color ColorFor(string c){switch(c){case "orange":return new Color(.92f,.42f,.31f);case "blue":return new Color(.25f,.48f,.86f);case "green":return new Color(.45f,.67f,.32f);case "yellow":return new Color(.96f,.70f,.18f);case "purple":return new Color(.55f,.39f,.72f);case "cyan":return new Color(.16f,.66f,.67f);case "red":return new Color(.88f,.25f,.38f);default:return new Color(.95f,.44f,.62f);}}
void Present(){foreach(var e in session.Events.ToArray()){if(e.kind==PresentationKind.Collection){Tone(620,.07f);Buzz();}if(e.kind==PresentationKind.HabitatComplete)Tone(820,.12f);if(e.kind==PresentationKind.ElevatorRelease)Tone(740,.08f);}session.Events.Clear();}
void Victory(){active=false;Tone(960,.2f);Buzz();winAt=save.reducedMotion?Time.unscaledTime+.15f:Time.unscaledTime+3.6f;save.completed=save.completed.Union(new[]{current}).ToList();save.highest=Mathf.Max(save.highest,Mathf.Min(18,current+1));var b=save.best.FirstOrDefault(x=>x.level==current);if(b==null)save.best.Add(new Best{level=current,moves=session.Committed.moves});else b.moves=Mathf.Min(b.moves,session.Committed.moves);save.snapshot=null;save.snapshotLevel=0;Store();}
void GameplayUi(){var root=HudRoot();Button(root.transform,"‹",new Vector2(.08f,.95f),new Vector2(110,90),ShowLevels);hud=HudLabel(root.transform,"LEVEL "+current.ToString("00")+" • MOVES 0",new Vector2(.5f,.95f),new Vector2(480,80));Button(root.transform,"Ⅱ",new Vector2(.92f,.95f),new Vector2(110,90),ShowPause);Button(root.transform,"↶",new Vector2(.30f,.08f),new Vector2(130,110),()=>{if(session.Undo()){Render(session.Committed);UpdateHud();SaveSnapshot();}});Button(root.transform,"↻",new Vector2(.50f,.08f),new Vector2(130,110),()=>{session.Restart();Render(session.Committed);UpdateHud();SaveSnapshot();});Button(root.transform,"⚙",new Vector2(.70f,.08f),new Vector2(130,110),ShowPause);if(current>=8)Button(root.transform,"✦",new Vector2(.14f,.20f),new Vector2(110,80),()=>ChooseAssist(AssistKind.NestBloom));if(current>=12)Button(root.transform,"↔",new Vector2(.86f,.20f),new Vector2(110,80),()=>ChooseAssist(AssistKind.GardenShift));if(current>=16)Button(root.transform,"✂",new Vector2(.86f,.31f),new Vector2(110,80),()=>ChooseAssist(AssistKind.RootTrim));}
void ChooseAssist(AssistKind k){if(ChargeFor(k)<=0)return;assist=k;assistHabitat=assistSprout=null;hud.text="SELECT HABITAT";}
void AssistTap(Vector2 p){var h=session.Committed.habitats.FirstOrDefault(x=>x.shape.Any(c=>p.x>=x.anchor.x+c.x&&p.x<=x.anchor.x+c.x+1&&p.y>=x.anchor.y+c.y&&p.y<=x.anchor.y+c.y+1));var s=session.Committed.sprouts.FirstOrDefault(x=>(x.position-p).sqrMagnitude<.2f);if(assist==AssistKind.RootTrim&&h!=null){var leaf=new Vector2Int(Mathf.FloorToInt(p.x-h.anchor.x),Mathf.FloorToInt(p.y-h.anchor.y));Use(assist.Value,h.id,"",leaf);return;}if(assistHabitat==null&&h!=null){assistHabitat=h.id;hud.text="SELECT MATCHING SPROUT";return;}if(assistSprout==null&&s!=null){assistSprout=s.id;Use(assist.Value,assistHabitat,assistSprout,Vector2Int.zero);}}
void Use(AssistKind k,string h,string s,Vector2Int leaf){if(session.UseAssist(k,h,s,leaf)){Spend(k);Render(session.Committed);Present();SaveSnapshot();}assist=null;UpdateHud();if(session.Committed.won)Victory();}
int ChargeFor(AssistKind k){if(Debug.isDebugBuild)return 999;var c=Ledger();return k==AssistKind.NestBloom?c.nest:k==AssistKind.GardenShift?c.garden:c.trim;}void Spend(AssistKind k){if(Debug.isDebugBuild)return;var c=Ledger();if(k==AssistKind.NestBloom)c.nest--;else if(k==AssistKind.GardenShift)c.garden--;else c.trim--;Store();}Charge Ledger(){var c=save.charges.FirstOrDefault(x=>x.level==current);if(c==null){c=new Charge{level=current,nest=current>=8?1:0,garden=current>=12?1:0,trim=current>=16?1:0};save.charges.Add(c);}return c;}
void UpdateHud(){if(hud!=null)hud.text="LEVEL "+current.ToString("00")+" • MOVES "+session.Committed.moves;}
void ShowHome(){active=false;ClearWorld();ClearUi();var p=Panel("Habitat Shift");Label(p.transform,"HABITAT SHIFT",66);Label(p.transform,"Tiny Friends. Brighter Spaces.",28);Button(p.transform,"CONTINUE",()=>StartLevel(Mathf.Clamp(save.last,1,save.highest)));Button(p.transform,"LEVELS",ShowLevels);Button(p.transform,"SETTINGS",ShowSettings);}
void ShowLevels(){active=false;ClearWorld();ClearUi();var p=Panel("Levels");Label(p.transform,"SELECT LEVEL",48);var grid=new GameObject("Level Grid",typeof(GridLayoutGroup),typeof(LayoutElement));grid.transform.SetParent(p.transform,false);var layout=grid.GetComponent<GridLayoutGroup>();layout.constraint=GridLayoutGroup.Constraint.FixedColumnCount;layout.constraintCount=3;layout.cellSize=new Vector2(220,105);layout.spacing=new Vector2(22,22);layout.childAlignment=TextAnchor.MiddleCenter;grid.GetComponent<LayoutElement>().preferredHeight=760;for(int i=1;i<=18;i++){var id=i;Button(grid.transform,id<=save.highest?"LEVEL "+id.ToString("00"):"LOCKED",()=>{if(id<=save.highest)StartLevel(id);},id>save.highest);}Button(p.transform,"HOME",ShowHome);}
