void Tutorial(int id){var p=Panel("Tutorial");Label(p.transform,"NEW ASSIST",48);Label(p.transform,id==8?"Nest Bloom: choose a habitat, then a nearby matching Sproutling.":id==12?"Garden Shift: choose a Sproutling, then its matching Habitat.":"Root Trim: select a leaf cell to make a path.",26);Button(p.transform,"GOT IT",()=>Destroy(p));}
