GameObject Panel(string n){var g=new GameObject(n,typeof(Image),typeof(VerticalLayoutGroup));g.transform.SetParent(canvas.transform,false);var im=g.GetComponent<Image>();im.color=new Color(1,.96f,.86f,.96f);var r=g.GetComponent<RectTransform>();r.anchorMin=Vector2.zero;r.anchorMax=Vector2.one;r.offsetMin=r.offsetMax=Vector2.zero;var v=g.GetComponent<VerticalLayoutGroup>();v.padding=new RectOffset(80,80,150,150);v.spacing=24;v.childAlignment=TextAnchor.MiddleCenter;ui.Add(g);return g;}GameObject HudRoot(){var g=new GameObject("HUD",typeof(Image),typeof(SafeAreaFitter));g.transform.SetParent(canvas.transform,false);g.GetComponent<Image>().color=Color.clear;g.GetComponent<Image>().raycastTarget=false;var r=g.GetComponent<RectTransform>();r.anchorMin=Vector2.zero;r.anchorMax=Vector2.one;r.offsetMin=r.offsetMax=Vector2.zero;g.GetComponent<SafeAreaFitter>().Refresh();ui.Add(g);return g;}void Label(Transform p,string t,int size){var g=new GameObject("Label",typeof(Text),typeof(LayoutElement));g.transform.SetParent(p,false);var x=g.GetComponent<Text>();x.font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");x.text=t;x.fontSize=size;x.fontStyle=FontStyle.Bold;x.alignment=TextAnchor.MiddleCenter;x.color=new Color(.23f,.18f,.14f);g.GetComponent<LayoutElement>().minHeight=size+40;}Text HudLabel(Transform p,string t,Vector2 a,Vector2 sz){var g=new GameObject("Hud",typeof(Text));g.transform.SetParent(p,false);var r=g.GetComponent<RectTransform>();r.anchorMin=r.anchorMax=a;r.anchoredPosition=Vector2.zero;r.sizeDelta=sz;var x=g.GetComponent<Text>();x.font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");x.text=t;x.fontSize=28;x.fontStyle=FontStyle.Bold;x.alignment=TextAnchor.MiddleCenter;x.color=new Color(.25f,.18f,.14f);x.raycastTarget=false;return x;}void Button(Transform p,string t,Action a,bool off=false){var g=new GameObject("Button",typeof(Image),typeof(Button),typeof(LayoutElement));g.transform.SetParent(p,false);g.GetComponent<Image>().color=off?Color.gray:new Color(.38f,.62f,.34f);g.GetComponent<Button>().interactable=!off;g.GetComponent<Button>().onClick.AddListener(()=>{if(!off){Buzz();a();}});g.GetComponent<LayoutElement>().preferredHeight=92;var x=new GameObject("Text",typeof(Text)).GetComponent<Text>();x.transform.SetParent(g.transform,false);x.font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");x.text=t;x.fontSize=26;x.fontStyle=FontStyle.Bold;x.alignment=TextAnchor.MiddleCenter;x.color=Color.white;var xr=x.GetComponent<RectTransform>();xr.anchorMin=Vector2.zero;xr.anchorMax=Vector2.one;xr.offsetMin=xr.offsetMax=Vector2.zero;}void Button(Transform p,string t,Vector2 a,Vector2 sz,Action f){var g=new GameObject("HudButton",typeof(Image),typeof(Button));g.transform.SetParent(p,false);var r=g.GetComponent<RectTransform>();r.anchorMin=r.anchorMax=a;r.sizeDelta=sz;g.GetComponent<Image>().color=new Color(.38f,.62f,.34f);g.GetComponent<Button>().onClick.AddListener(()=>{Buzz();f();});var label=new GameObject("Text",typeof(Text));label.transform.SetParent(g.transform,false);var x=label.GetComponent<Text>();x.font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");x.text=t;x.fontSize=30;x.fontStyle=FontStyle.Bold;x.alignment=TextAnchor.MiddleCenter;x.color=Color.white;var lr=label.GetComponent<RectTransform>();lr.anchorMin=Vector2.zero;lr.anchorMax=Vector2.one;lr.offsetMin=lr.offsetMax=Vector2.zero;}
void ClearUi(){foreach(var x in ui)if(x!=null)Destroy(x);ui.Clear();hud=null;}void ClearWorld(){if(presentation!=null)presentation.Clear();}void SaveSnapshot(){save.last=current;save.snapshotLevel=current;save.snapshot=session.Committed.Clone();Store();}SaveV2 Load(){var p=Path.Combine(Application.persistentDataPath,"habitat_shift_save_v2.json");try{if(File.Exists(p))return JsonUtility.FromJson<SaveV2>(File.ReadAllText(p))??new SaveV2();var old=Path.Combine(Application.persistentDataPath,"habitat_shift_save.json");if(File.Exists(old)){var legacy=JsonUtility.FromJson<LegacyPrefs>(File.ReadAllText(old))??new LegacyPrefs();return new SaveV2{music=legacy.Sound,sfx=legacy.Sound,haptics=legacy.Haptics,reducedMotion=legacy.ReducedMotion};}return new SaveV2();}catch{return new SaveV2();}}void Store(){File.WriteAllText(Path.Combine(Application.persistentDataPath,"habitat_shift_save_v2.json"),JsonUtility.ToJson(save));}void Buzz(){if(save.haptics&&Application.isMobilePlatform)Handheld.Vibrate();}void Tone(float hz,float len){if(!save.sfx)return;int n=Mathf.CeilToInt(22050*len);var c=AudioClip.Create("tone",n,1,22050,false);var d=new float[n];for(int i=0;i<n;i++)d[i]=Mathf.Sin(i*hz*2*Mathf.PI/22050f)*.1f*(1-i/(float)n);c.SetData(d,0);audio.PlayOneShot(c);}
}}








